function scr_weaponget(q2k) {
  this.noroom = 0;
  let q2T = 0;
  let q2P = 0;
  if (q2T === 0) {
    let q2h = 0;
    kq(this, "__weapon")[0] = q2k;
    q2P = 0;
    for (; q2P < 48; q2P++) {
      if (Pz.weapon[q2P] !== 0) {
        kq(this, "__weapon")[q2h + 1] = Pz.weapon[q2P];
        q2h++;
      }
    }
    if (q2h >= 48) {
      this.noroom = 1;
    } else {
      for (q2P = 0; q2P < 48; q2P++) {
        if (q2P <= q2h) {
          kq(Pz, "weapon")[q2P] = this.__weapon[q2P];
        } else {
          kq(Pz, "weapon")[q2P] = 0;
        }
      }
    }
  } else if (DQ(q2T)) {
    this.loop = 1;
    kq(Pz, "weapon")[48] = 999;
    for (let q2D = 0; this.loop === 1;) {
      if (++q2D > 5000000) {
        throw new Error("GML loop ran 5000000 times without ending");
      }
      if (Pz.weapon[q2P] === 0) {
        kq(Pz, "weapon")[q2P] = q2k;
        break;
      }
      if (q2P === 48) {
        this.noroom = 1;
        break;
      }
      q2P += 1;
    }
  }
  jU(this, gS("scr_weaponinfo_all"));
}
