function scr_ease_inout(q2k, q2T) {
  if (q2T < -3 || q2T > 7) {
    return q2k;
  } else if (q2T === -3) {
    return gS("ease_inout_bounce").call(this, q2k, 0, 1, 1);
  } else if (q2T === -2) {
    return gS("ease_inout_elastic").call(this, q2k, 0, 1, 1);
  } else if (q2T === -1) {
    return gS("ease_inout_back").call(this, q2k, 0, 1, 1);
  } else if (q2T === 1) {
    return D9(Math.PI * q2k - 1) * -0.5;
  } else if (q2T === 0) {
    return q2k;
  } else {
    q2k *= 2;
    if (q2k < 1) {
      return gS("scr_ease_in").call(this, q2k, q2T) * 0.5;
    } else {
      q2k--;
      return (gS("scr_ease_out").call(this, q2k, q2T) + 1) * 0.5;
    }
  }
}
